function clearFilters(){filters={...filters,radius:10,minRate:0,industries:[],time:'all',noExperience:false,noEnglish:false,trainingProvided:false,lightWork:false,outfitProvided:false,sameDayPay:false,noQualifications:false};syncFilterForm()}
function clearAiResults(){aiMatchedIds=null;renderJobs()}
function parseAssistant(text){const t=text.toLowerCase().replace(/,/g,' '),days={monday:/poniedział|poniedzial/,tuesday:/wtorek|wtorku/,wednesday:/środ|srod/};let day=Object.keys(days).find(k=>days[k].test(t));const windows=[...t.matchAll(/(?:od\s*)?(\d{1,2})(?::\d{2})?\s*(?:-|–|do)\s*(\d{1,2})(?::\d{2})?/g)].map(m=>[+m[1],+m[2]]);const after=t.match(/po\s+(\d{1,2})/),before=t.match(/(?:przed|do)\s+(\d{1,2})/);if(!windows.length&&after)windows.push([+after[1],24]);if(!windows.length&&before)windows.push([0,+before[1]]);const rateMatch=t.match(/(?:minimum|min\.?|od)\s*(\d{2})\s*zł/),radiusMatch=t.match(/(?:do|promieniu)\s*(\d{1,2})\s*km/);const industries=[];if(/biur|recepc/.test(t))industries.push('office');if(/event|wydarze/.test(t))industries.push('events');if(/sklep|retail|inwent/.test(t))industries.push('retail');if(/logisty|magaz|paczk|przesył/.test(t))industries.push('logistics');if(/teren|ankiet/.test(t))industries.push('field');return{day,windows,minRate:rateMatch?+rateMatch[1]:0,radius:radiusMatch?+radiusMatch[1]:null,industries}}
function assistantSearch(text){const p=parseAssistant(text);let matches=jobs.filter(j=>j.active!==false&&!jobIsTaken(j)&&(!p.day||j.day===p.day)&&(!p.windows.length||p.windows.some(([a,b])=>j.start>=a&&j.end<=b))&&j.rate>=p.minRate&&(!p.radius||jobDistance(j)<=p.radius)&&(!p.industries.length||p.industries.includes(j.industry)));return{parsed:p,matches}}
function addChat(text,type){const el=document.createElement('div');el.className=`chat-message ${type}`;el.innerHTML=text;document.querySelector('#assistantChat').appendChild(el);document.querySelector('#assistantChat').scrollTop=99999;return el}
function handleAssistant(text){if(!text.trim())return;addChat(text,'user');const {parsed,matches}=assistantSearch(text);setTimeout(()=>{const understood=[parsed.day&&({monday:'poniedziałek',tuesday:'wtorek',wednesday:'środę'}[parsed.day]),parsed.windows.length&&parsed.windows.map(x=>`${x[0]}:00–${x[1]}:00`).join(' lub '),parsed.minRate&&`min. ${parsed.minRate} zł/h`,parsed.radius&&`do ${parsed.radius} km`].filter(Boolean).join(', ');const cards=matches.map(j=>`<div class="ai-result"><div><strong>${j.role}</strong><small>${j.date} · ${j.time} · ${j.area}</small></div><b>${j.rate} zł/h</b></div>`).join('');const msg=matches.length?`Rozumiem: <strong>${understood||'elastyczny grafik'}</strong>. Znalazłem ${matches.length} ${matches.length===1?'pasującą zmianę':'pasujące zmiany'}:${cards}<button class="show-ai-results">Pokaż te oferty</button>`:`Rozumiem: <strong>${understood||'podane preferencje'}</strong>. Nie mam teraz idealnego dopasowania. Spróbuj poszerzyć godziny albo promień.`;const el=addChat(msg,'bot');const btn=el.querySelector('.show-ai-results');if(btn)btn.onclick=()=>{aiMatchedIds=matches.map(j=>j.id);activeDate='all';document.querySelectorAll('.filter[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter==='all'));assistantModal.close();renderJobs();toast('Pokazuję oferty wybrane przez asystenta.')}} ,350)}
