function openAdminEmployer(email){const owned=jobs.filter(j=>j.ownerEmail===email);if(!owned.length)return;const active=owned.filter(j=>j.active!==false),company=owned[0].company,applicants=owned.reduce((sum,j)=>sum+(j.applicants||0),0),value=active.reduce((sum,j)=>sum+j.rate*(j.end-j.start),0);showAdminDetails(`<div class="admin-detail-head"><div class="avatar large blue">${company.slice(0,2).toUpperCase()}</div><div><p class="eyebrow">ZLECENIODAWCA</p><h2>${company}</h2><span class="status active">Aktywny</span></div></div><div class="admin-detail-grid"><div><small>KONTO / IDENTYFIKATOR</small><strong>${email}</strong></div><div><small>OFERTY</small><strong>${active.length} aktywnych · ${owned.length-active.length} wstrzymanych</strong></div><div><small>ZGŁOSZENIA</small><strong>${applicants}</strong></div><div><small>WARTOŚĆ AKTYWNYCH ZMIAN</small><strong>${value.toLocaleString('pl-PL')} zł</strong></div></div>`) }
