function editAdminJob(id){const j=jobs.find(x=>x.id===id);if(!canManageJob(j)||!j)return;editingJobId=id;const form=document.querySelector('#adminJobForm'),d=getJobDetails(j),clock=n=>`${String(Math.floor(n)).padStart(2,'0')}:${String(Math.round(n%1*60)).padStart(2,'0')}`;form.elements.role.value=j.role;form.elements.company.value=j.company;form.elements.area.value=j.area;form.elements.address.value=d.address;form.elements.contactName.value=d.contactName;form.elements.contactPhone.value=d.contactPhone;form.elements.day.value=j.day;form.elements.industry.value=j.industry;form.elements.start.value=clock(j.start);form.elements.end.value=clock(j.end);form.elements.rate.value=j.rate;form.elements.tasks.value=(j.tasks||[]).join(', ');form.elements.arrival.value=d.arrival;form.elements.dressCode.value=d.dressCode;form.elements.documents.value=d.documents;form.elements.instructions.value=d.instructions;document.querySelector('#jobFormEyebrow').textContent='EDYCJA OFERTY';document.querySelector('#jobFormTitle').textContent=j.role;document.querySelector('#jobFormSubmit').textContent='Zapisz zmiany';document.querySelector('#jobFormModal').showModal()}
function addAdminJob(form){if(!canManageJobs())return;const d=new FormData(form),days={monday:'Poniedziałek',tuesday:'Wtorek',wednesday:'Środa'},icons={office:'▤',events:'✦',retail:'◼',logistics:'⌂',field:'◎'},start=d.get('start'),end=d.get('end'),industry=d.get('industry');if(end<=start)return toast('Godzina zakończenia musi być późniejsza niż rozpoczęcia.');const values={role:d.get('role').trim(),company:d.get('company').trim(),icon:icons[industry],date:days[d.get('day')],day:d.get('day'),time:`${start}–${end}`,start:+start.split(':')[0]+(+start.split(':')[1]/60),end:+end.split(':')[0]+(+end.split(':')[1]/60),rate:+d.get('rate'),area:d.get('area').trim(),industry,tasks:d.get('tasks').split(',').map(x=>x.trim()).filter(Boolean),address:d.get('address').trim(),contactName:d.get('contactName').trim(),contactPhone:d.get('contactPhone').trim(),arrival:d.get('arrival').trim(),dressCode:d.get('dressCode').trim(),documents:d.get('documents').trim(),instructions:d.get('instructions').trim()};if(editingJobId){const edited=jobs.find(x=>x.id===editingJobId);if(!canManageJob(edited))return;Object.assign(edited,values)}else{jobs.unshift({id:Date.now(),...values,ownerEmail:authUser.email,applicants:0,lat:52.2297,lng:21.0122,match:90,color:'#dbeee6',newness:Date.now(),experience:false,english:false,active:true})}saveJobs();document.querySelector('#jobFormModal').close();form.reset();toast(editingJobId?'Zmiany w ofercie zostały zapisane.':'Nowa oferta została opublikowana.');editingJobId=null}
function switchAuthTab(tab){document.querySelectorAll('[data-auth-tab]').forEach(b=>b.classList.toggle('active',b.dataset.authTab===tab));document.querySelector('#loginForm').classList.toggle('hidden',tab!=='login');document.querySelector('#registerForm').classList.toggle('hidden',tab!=='register');document.querySelector('#loginError').textContent='';document.querySelector('#registerError').textContent=''}
function openAuth(tab='login',action=null){pendingAuthAction=action;if(jobModal.open)jobModal.close();switchAuthTab(tab);document.querySelector('#authModal').showModal();setTimeout(()=>document.querySelector(`#${tab}Form input`).focus(),100)}
function requireAuth(action){if(authUser)return action();openAuth('login',action)}
function finishAuth(user){authUser={firstName:user.firstName,lastName:user.lastName,email:user.email,role:user.role||'user'};localStorage.setItem('flexo-session',JSON.stringify(authUser));document.querySelector('#authModal').close();renderAuthState();renderJobs();renderBooked();renderAdminJobs();renderWorkerNotifications();toast(`Witaj, ${user.firstName}!`);const action=pendingAuthAction;pendingAuthAction=null;if(authUser.role==='employer')switchView('employer');else if(authUser.role==='admin')switchView('admin');else if(action)setTimeout(action,150);else switchView('discover')}
function login(form){const d=new FormData(form),email=d.get('email').trim().toLowerCase(),user=registeredUsers.find(x=>x.email.toLowerCase()===email&&x.password===d.get('password'));if(!user){document.querySelector('#loginError').textContent='Nieprawidłowy e-mail lub hasło.';return}finishAuth(user);form.reset()}
function register(form){const d=new FormData(form),email=d.get('email').trim().toLowerCase();if(registeredUsers.some(x=>x.email.toLowerCase()===email)){document.querySelector('#registerError').textContent='Konto z tym adresem już istnieje.';return}const user={firstName:d.get('firstName').trim(),lastName:d.get('lastName').trim(),email,password:d.get('password'),role:'user'};registeredUsers.push(user);localStorage.setItem('flexo-users',JSON.stringify(registeredUsers));userProfile={...userProfile,firstName:user.firstName,lastName:user.lastName,email:user.email};localStorage.setItem('flexo-profile',JSON.stringify(userProfile));renderProfile();finishAuth(user);form.reset()}
function renderAuthState(){const sidebar=document.querySelector('.sidebar-user'),mobile=document.querySelector('#mobileAccountAction'),isAdmin=authUser?.role==='admin',isEmployer=authUser?.role==='employer',workerViews=['discover','schedule','wallet','profile'];document.querySelectorAll('[data-view="admin"]').forEach(x=>x.hidden=!isAdmin);document.querySelectorAll('[data-view="employer"]').forEach(x=>x.hidden=!isEmployer);document.querySelectorAll('[data-view]').forEach(x=>{if(workerViews.includes(x.dataset.view))x.hidden=isAdmin||isEmployer});if(!isAdmin&&document.querySelector('#admin').classList.contains('active-view'))switchView(isEmployer?'employer':'discover');if(!isEmployer&&document.querySelector('#employer').classList.contains('active-view'))switchView(isAdmin?'admin':'discover');if(authUser){const roleLabel=isAdmin?'Administrator':isEmployer?'Pracodawca':userProfile.city,avatar=isAdmin?'AF':isEmployer?'EC':initials();sidebar.classList.remove('guest');sidebar.querySelector('strong').textContent=authUser.firstName;sidebar.querySelector('small').textContent=roleLabel;sidebar.querySelector('.avatar').textContent=avatar;document.querySelector('#accountAction').textContent='Wyjdź';document.querySelector('#accountAction').title='Wyloguj się';mobile.classList.remove('guest');mobile.textContent=avatar}else{sidebar.classList.add('guest');sidebar.querySelector('strong').textContent='Gość';sidebar.querySelector('small').textContent='Przeglądasz bez konta';sidebar.querySelector('.avatar').textContent='?';document.querySelector('#accountAction').textContent='Zaloguj';document.querySelector('#accountAction').title='Zaloguj się';mobile.classList.add('guest');mobile.textContent='?'}}
function accountAction(){if(!authUser)return openAuth();if(confirm('Czy chcesz się wylogować?')){authUser=null;localStorage.removeItem('flexo-session');renderAuthState();renderAdminJobs();switchView('discover');toast('Wylogowano. Nadal możesz przeglądać oferty.')}}
