function openMapJob(id){document.querySelector('#mapModal').close();setTimeout(()=>openJob(id),100)}
function setupDemoAccounts(){const box=document.createElement('div');box.className='demo-accounts';box.innerHTML='<small>KONTA TESTOWE</small><div><button data-demo="lukasz@example.pl|flexo123">Pracownik</button><button data-demo="firma@flexo.pl|firma123">Pracodawca</button><button data-demo="admin@flexo.pl|admin123">Administrator</button></div>';document.querySelector('#authModal').insertBefore(box,document.querySelector('.auth-security'));box.querySelectorAll('[data-demo]').forEach(button=>button.onclick=()=>{const [email,password]=button.dataset.demo.split('|'),form=document.querySelector('#loginForm');switchAuthTab('login');form.elements.email.value=email;form.elements.password.value=password;form.elements.email.focus()})}
function setupAdminDetails(){const modal=document.createElement('dialog');modal.id='adminDetailsModal';modal.className='admin-details-modal';modal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><div id="adminDetailsContent"></div>';document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close()}
function initMap(){if(typeof L==='undefined'){toast('Mapa nie mogła zostać załadowana. Sprawdź połączenie z internetem.');return}if(!jobsMap){jobsMap=L.map('jobsMap',{zoomControl:true}).setView([userLocation.lat,userLocation.lng],13);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(jobsMap);jobMapLayer=L.layerGroup().addTo(jobsMap);startMarker=L.marker([userLocation.lat,userLocation.lng],{draggable:true,title:'Punkt startowy'}).addTo(jobsMap).bindTooltip('Twój punkt startowy');radiusCircle=L.circle([userLocation.lat,userLocation.lng],{radius:filters.radius*1000,color:'#0d5b48',fillColor:'#bdf5da',fillOpacity:.16,weight:2}).addTo(jobsMap);startMarker.on('dragend',e=>setMapOrigin(e.target.getLatLng()));jobsMap.on('click',e=>setMapOrigin(e.latlng))}setTimeout(()=>{jobsMap.invalidateSize();updateMap()},50)}
function setMapOrigin(pos){userLocation={lat:pos.lat,lng:pos.lng,label:'Wybrany punkt na mapie'};locationFilterEnabled=true;updateMap()}
function clearRoute(){routeRequestId++;if(routeLine&&jobsMap)jobsMap.removeLayer(routeLine);routeLine=null;selectedMapJobId=null;document.querySelector('#routeSummary').hidden=true}
async function drawRouteToJob(id,fit=true){if(!locationFilterEnabled)return toast('Najpierw ustaw punkt startowy lub użyj swojej lokalizacji.');const job=jobs.find(j=>j.id===id);if(!job)return;selectedMapJobId=id;const requestId=++routeRequestId,profiles={walk:'foot',bike:'bike',transit:'car',car:'car'},profile=profiles[travelMode],url=`https://routing.openstreetmap.de/routed-${profile}/route/v1/driving/${userLocation.lng},${userLocation.lat};${job.lng},${job.lat}?overview=full&geometries=geojson`;const modeIcons={walk:'🚶',bike:'🚲',transit:'🚌',car:'🚗'},summary=document.querySelector('#routeSummary');document.querySelector('#routeIcon').textContent=modeIcons[travelMode];document.querySelector('#routeJobName').textContent=job.role;document.querySelector('#routeMeta').textContent='Wyznaczam trasę po drogach…';summary.hidden=false;try{const response=await fetch(url);if(!response.ok)throw new Error('routing');const data=await response.json();if(requestId!==routeRequestId||!data.routes?.length)return;const route=data.routes[0],points=route.geometry.coordinates.map(([lng,lat])=>[lat,lng]);if(routeLine)jobsMap.removeLayer(routeLine);routeLine=L.polyline(points,{color:'#0d5b48',weight:5,opacity:.9}).addTo(jobsMap);let minutes=Math.max(1,Math.round(route.duration/60));if(travelMode==='transit')minutes=Math.round(minutes*1.25+8);const label=travelMode==='transit'?'komunikacją (orientacyjnie)':estimateTravel(job).label;document.querySelector('#routeMeta').textContent=`${(route.distance/1000).toFixed(1).replace('.',',')} km · około ${minutes} min ${label}`;if(fit)jobsMap.fitBounds(routeLine.getBounds().pad(.15),{maxZoom:15})}catch(error){if(requestId!==routeRequestId)return;document.querySelector('#routeMeta').textContent='Nie udało się teraz wyznaczyć trasy. Spróbuj ponownie.';toast('Serwis trasowania jest chwilowo niedostępny.')}}
function clearLocationFilter(){locationFilterEnabled=false;clearRoute();renderJobs();updateMap();toast('Filtrowanie według lokalizacji zostało wyłączone.')}
function updateMap(){if(!jobsMap)return;startMarker.setLatLng([userLocation.lat,userLocation.lng]).setOpacity(locationFilterEnabled?1:.45);radiusCircle.setLatLng([userLocation.lat,userLocation.lng]).setRadius(filters.radius*1000).setStyle({opacity:locationFilterEnabled?1:0,fillOpacity:locationFilterEnabled?0.16:0});jobMapLayer.clearLayers();let count=0;jobs.filter(j=>j.active!==false&&!jobIsTaken(j)).forEach(j=>{const within=!locationFilterEnabled||jobDistance(j)<=filters.radius,trip=estimateTravel(j);if(within)count++;const popup=`<div class="map-job-popup"><strong>${j.role}</strong><small>${j.company} · ${j.area}</small><small>${j.date}, ${j.time} · ${j.rate} zł/h</small>${locationFilterEnabled?`<small>${jobDistance(j).toFixed(1).replace('.',',')} km · około ${trip.minutes} min ${trip.label}</small>`:''}<button onclick="openMapJob(${j.id})">Zobacz zlecenie →</button></div>`,marker=L.circleMarker([j.lat,j.lng],{radius:within?9:6,color:within?'#0d5b48':'#8f9c97',fillColor:within?'#d8ff70':'#d9dfdc',fillOpacity:1,weight:2,opacity:within?1:.55,bubblingMouseEvents:false}).addTo(jobMapLayer).bindPopup(popup,{minWidth:190});marker.on('click',()=>drawRouteToJob(j.id,true))});document.querySelector('#mapJobsCount').textContent=count;document.querySelector('#mapLocationLabel').textContent=locationFilterEnabled?userLocation.label:'Nie wybrano';document.querySelector('#mapRadiusOutput').value=filters.radius;document.querySelector('#mapRadius').value=filters.radius;document.querySelector('#mapClearLocation').hidden=!locationFilterEnabled;document.querySelector('#clearLocation').hidden=!locationFilterEnabled;if(selectedMapJobId&&locationFilterEnabled)drawRouteToJob(selectedMapJobId,false)}
function openMap(){document.querySelector('#mapModal').showModal();document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===travelMode));initMap()}
function fitAllMapJobs(){if(!jobsMap)return;const points=jobs.filter(j=>j.active!==false&&!jobIsTaken(j)).map(j=>[j.lat,j.lng]);if(locationFilterEnabled)points.push([userLocation.lat,userLocation.lng]);if(points.length)jobsMap.fitBounds(L.latLngBounds(points).pad(.18),{maxZoom:13});toast('Mapa pokazuje wszystkie dostępne oferty.')}
function saveApplications(){localStorage.setItem('flexo-applications',JSON.stringify(applications));jobs.forEach(j=>j.applicants=applications.filter(a=>a.jobId===j.id).length)}
function expireApplications(){let changed=false;applications.forEach(a=>{if(a.status==='pending'&&Date.now()>a.deadline){a.status='expired';changed=true}});if(changed)saveApplications();return changed}
function myApplication(jobId){return applications.find(a=>a.jobId===jobId&&a.workerEmail===authUser?.email)}
function confirmedJobIdsFor(email){return applications.filter(a=>a.workerEmail===email&&['confirmed','completed'].includes(a.status)).map(a=>a.jobId)}
function applicationStatusText(status){return{pending:'Oczekuje na potwierdzenie pracodawcy',confirmed:'Zlecenie potwierdzone',completed:'Zmiana wykonana i oceniona',rejected:'Pracodawca wybrał inną osobę',expired:'Czas na decyzję pracodawcy minął',worker_cancelled:'Pracownik zrezygnował ze zmiany',employer_cancelled:'Pracodawca anulował zmianę'}[status]||''}
function submitApplication(id){if(!authUser)return openAuth('login',()=>submitApplication(id));if(authUser.role!=='user')return toast('Na zlecenia mogą zgłaszać się tylko pracownicy.');expireApplications();const app=myApplication(id);if(app)return toast(applicationStatusText(app.status));const workerName=`${authUser.firstName} ${authUser.lastName}`;applications.push({id:`${id}-${authUser.email}-${Date.now()}`,jobId:id,workerEmail:authUser.email,workerName,status:'pending',appliedAt:Date.now(),deadline:Date.now()+APPLICATION_DECISION_MS});saveApplications();renderJobs();renderWorkerNotifications();openJob(id);toast('Zgłoszenie wysłane. Pracodawca ma 5 minut na decyzję.')}
function remainingTime(deadline){const seconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));return`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
function renderWorkerNotifications(){expireApplications();const box=document.querySelector('#workerNotifications');if(!box)return;if(authUser?.role!=='user'){box.hidden=true;return}const mine=applications.filter(a=>a.workerEmail===authUser.email).sort((a,b)=>b.appliedAt-a.appliedAt);box.hidden=!mine.length;box.innerHTML=mine.map(a=>{const j=jobs.find(x=>x.id===a.jobId);if(!j)return'';const texts={pending:['Oczekuje na potwierdzenie',`Pracodawca wybiera kandydata · pozostało <b data-deadline="${a.deadline}">${remainingTime(a.deadline)}</b>`],confirmed:['Zlecenie potwierdzone ✓','Pracodawca wybrał Ciebie. Zmiana jest w Twoim kalendarzu.'],rejected:['Wybrano inną osobę','Tym razem pracodawca wybrał innego kandydata. Może następnym razem!'],expired:['Brak decyzji w wymaganym czasie','Zgłoszenie wygasło — możesz wybrać inną zmianę.']}[a.status];return`<article class="application-notice ${a.status}"><span>${a.status==='confirmed'?'✓':a.status==='pending'?'◷':'i'}</span><div><small>${j.role} · ${j.company}</small><strong>${texts[0]}</strong><p>${texts[1]}</p></div>${a.status==='confirmed'?`<button onclick="openJob(${j.id})">Szczegóły</button>`:''}</article>`}).join('')}
function candidateProfile(email,name){const known={'lukasz@example.pl':{attendance:98,cancellations:1,city:'Warszawa',skills:['Logistyka','Obsługa wydarzeń','Punktualność']},'maria@example.pl':{attendance:96,cancellations:2,city:'Warszawa',skills:['Obsługa klienta','Rejestracja gości','Eventy']},'jan@example.pl':{attendance:94,cancellations:1,city:'Warszawa',skills:['Logistyka','Pakowanie','Praca zespołowa']}},base=known[email]||{attendance:97,cancellations:0,city:userProfile.city||'Warszawa',skills:userProfile.skills?.length?userProfile.skills:['Dyspozycyjność','Punktualność']},workerReviews=reviews.filter(r=>r.workerEmail===email),rating=workerReviews.length?Math.round(workerReviews.reduce((sum,r)=>sum+r.score,0)/workerReviews.length*10)/10:null;return{...base,rating,completed:workerReviews.length,reviews:workerReviews}}
function openCandidateProfile(email,jobId){const job=jobs.find(j=>j.id===jobId);if(!canManageJob(job))return;const app=applications.find(a=>a.jobId===jobId&&a.workerEmail===email);if(!app)return;const p=candidateProfile(email,app.workerName),modal=document.querySelector('#candidateProfileModal'),initials=app.workerName.split(' ').map(x=>x[0]).join('').slice(0,2);document.querySelector('#candidateProfileContent').innerHTML=`<div class="candidate-profile-head"><div class="avatar large">${initials}</div><div><p class="eyebrow">ZWERYFIKOWANY PRACOWNIK</p><h2>${app.workerName}</h2><p>${p.city} · <strong>${p.rating} ★</strong></p></div></div><div class="candidate-profile-stats"><div><small>OCENA</small><strong>${p.rating} / 5</strong></div><div><small>UKOŃCZONE ZMIANY</small><strong>${p.completed}</strong></div><div><small>FREKWENCJA</small><strong>${p.attendance}%</strong></div><div><small>ANULOWANIA</small><strong>${p.cancellations}</strong></div></div><div class="candidate-profile-section"><small>UMIEJĘTNOŚCI</small><div class="skill-tags">${p.skills.map(s=>`<span>${s}</span>`).join('')}</div></div><div class="candidate-fit"><strong>Dlaczego pasuje do tej zmiany?</strong><p>Potwierdził dostępność w godzinach ${job.time}, ma zweryfikowaną tożsamość i ${p.attendance}% frekwencji.</p></div>${app.status==='pending'?`<button class="candidate-confirm-main" onclick="document.querySelector('#candidateProfileModal').close();confirmCandidate('${app.id}')">Wybierz tego pracownika</button>`:`<div class="management-preview-note">${applicationStatusText(app.status)}</div>`}`;modal.showModal()}
function openCandidates(jobId){const job=jobs.find(j=>j.id===jobId);if(!canManageJob(job))return;expireApplications();const list=applications.filter(a=>a.jobId===jobId).sort((a,b)=>a.appliedAt-b.appliedAt),modal=document.querySelector('#candidatesModal');document.querySelector('#candidatesContent').innerHTML=`<div class="candidate-head"><p class="eyebrow">WYBÓR PRACOWNIKA</p><h2>${job.role}</h2><p>${job.company} · ${job.date}, ${job.time}</p></div><div class="candidate-list">${list.length?list.map(a=>`<div class="candidate-row ${a.status}"><div class="avatar">${a.workerName.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><strong>${a.workerName}</strong><small>${a.workerEmail}</small><span>${applicationStatusText(a.status)}${a.status==='pending'?` · <b data-deadline="${a.deadline}">${remainingTime(a.deadline)}</b>`:''}</span></div><div class="candidate-actions"><button class="profile-button" onclick="openCandidateProfile('${a.workerEmail}',${jobId})">Zobacz profil</button>${a.status==='pending'?`<button onclick="confirmCandidate('${a.id}')">Wybierz</button>`:`<em>${a.status==='confirmed'?'Wybrany':'Zakończone'}</em>`}</div></div>`).join(''):'<div class="empty">Nikt jeszcze nie zgłosił się do tej zmiany.</div>'}</div>`;modal.showModal()}
function confirmCandidate(applicationId){const chosen=applications.find(a=>a.id===applicationId);if(!chosen||chosen.status!=='pending')return;expireApplications();if(chosen.status!=='pending')return openCandidates(chosen.jobId);applications.forEach(a=>{if(a.jobId===chosen.jobId&&a.status==='pending')a.status=a.id===chosen.id?'confirmed':'rejected'});saveApplications();document.querySelector('#candidatesModal').close();renderJobs();if(jobsMap)updateMap();renderAdminJobs();renderWorkerNotifications();toast(`Wybrano: ${chosen.workerName}. Oferta została zdjęta z publicznej listy.`)}
function resetCandidateTest(){if(authUser?.role!=='employer')return toast('Test kandydatów uruchamia pracodawca.');const owned=jobs.filter(j=>j.ownerEmail===authUser.email&&j.active!==false),ids=new Set(owned.map(j=>j.id)),pool=[['Maria Nowak','maria@example.pl'],['Jan Wiśniewski','jan@example.pl'],['Kasia Zielińska','kasia@example.pl'],['Piotr Wójcik','piotr@example.pl'],['Anna Mazur','anna@example.pl'],['Tomasz Kurek','tomasz@example.pl']];applications=applications.filter(a=>!ids.has(a.jobId));owned.forEach((job,index)=>{for(let n=0;n<2;n++){const [workerName,workerEmail]=pool[(index*2+n)%pool.length],appliedAt=Date.now()+n*500;applications.push({id:`test-${job.id}-${workerEmail}-${Date.now()}`,jobId:job.id,workerEmail,workerName,status:'pending',appliedAt,deadline:appliedAt+APPLICATION_DECISION_MS})}});saveApplications();renderAdminJobs();toast(`Test uruchomiony: kandydaci czekają przy ${owned.length} ofertach. Masz 5 minut na decyzje.`)}
function setupApplicationWorkflow(){const notifications=document.createElement('div');notifications.id='workerNotifications';notifications.className='worker-notifications';notifications.hidden=true;document.querySelector('#discover .hero').after(notifications);const modal=document.createElement('dialog');modal.id='candidatesModal';modal.className='candidates-modal';modal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><div id="candidatesContent"></div>';document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close();const profileModal=document.createElement('dialog');profileModal.id='candidateProfileModal';profileModal.className='candidate-profile-modal';profileModal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><div id="candidateProfileContent"></div>';document.body.appendChild(profileModal);profileModal.querySelector('.modal-close').onclick=()=>profileModal.close();setInterval(()=>{if(expireApplications()){renderWorkerNotifications();renderAdminJobs()}document.querySelectorAll('[data-deadline]').forEach(el=>el.textContent=remainingTime(+el.dataset.deadline));document.querySelectorAll('[data-offer-deadline]').forEach(el=>{const left=Math.max(0,+el.dataset.offerDeadline-Date.now()),minutes=Math.floor(left/60000),days=Math.floor(minutes/1440),hours=Math.floor(minutes%1440/60),mins=minutes%60;el.textContent=`${el.closest('.offer-deadline')?'pozostało ':'Pozostało '}${days?`${days} d ${hours} godz.`:hours?`${hours} godz. ${mins} min`:`${Math.max(0,mins)} min`}`})},1000)}
