function submitReview(form){const workerEmail=form.workerEmail.value,jobId=+form.jobId.value,app=applications.find(a=>a.jobId===jobId&&a.workerEmail===workerEmail);if(!app||app.status!=='confirmed'||reviews.some(r=>r.workerEmail===workerEmail&&r.jobId===jobId&&r.employerEmail===authUser.email))return toast('Ta zmiana została już oceniona.');const punctuality=+form.punctuality.value,quality=+form.quality.value,cooperation=+form.cooperation.value,score=Math.round((punctuality+quality+cooperation)/3*10)/10,entry={id:`review-${jobId}-${workerEmail}`,workerEmail,jobId,employerEmail:authUser.email,punctuality,quality,cooperation,score,comment:form.comment.value.trim(),createdAt:Date.now()};reviews.push(entry);app.status='completed';saveReviews();saveApplications();document.querySelector('#reviewModal').close();document.querySelector('#candidateProfileModal')?.close();document.querySelector('#candidatesModal')?.close();renderAdminJobs();renderWorkerNotifications();renderDashboardSummary();toast(`Ocena ${score}/5 została zapisana. Zmiana została zakończona.`)}
function setupReviewWorkflow(){const modal=document.createElement('dialog');modal.id='reviewModal';modal.className='review-modal';modal.innerHTML=`<button class="modal-close" aria-label="Zamknij">×</button><form id="reviewForm" class="review-form"><input type="hidden" name="workerEmail"><input type="hidden" name="jobId"><p class="eyebrow">OCENA PO WYKONANEJ ZMIANIE</p><h2 data-worker></h2><p class="review-job" data-job></p><div class="review-grid">${[['punctuality','Punktualność'],['quality','Jakość pracy'],['cooperation','Współpraca']].map(([name,label])=>`<label>${label}<select name="${name}" required><option value="5">5 — świetnie</option><option value="4">4 — dobrze</option><option value="3">3 — poprawnie</option><option value="2">2 — słabo</option><option value="1">1 — bardzo słabo</option></select></label>`).join('')}</div><label class="review-comment">Komentarz (opcjonalnie)<textarea name="comment" rows="3" maxlength="300" placeholder="Co warto wiedzieć o współpracy?"></textarea></label><p class="review-note">Ocena profilu to średnia z trzech kryteriów ze wszystkich ukończonych zmian.</p><button class="candidate-confirm-main" type="submit">Zapisz ocenę i zakończ zmianę</button></form>`;document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close();modal.querySelector('form').onsubmit=e=>{e.preventDefault();submitReview(e.target)}}
function openCancellation(jobId){const job=jobs.find(j=>j.id===jobId),app=applications.find(a=>a.jobId===jobId&&a.status==='confirmed');if(!job||!app)return toast('Ta zmiana nie może już zostać anulowana.');const byWorker=authUser?.role==='user'&&app.workerEmail===authUser.email,byEmployer=['employer','admin'].includes(authUser?.role)&&canManageJob(job);if(!byWorker&&!byEmployer)return;const form=document.querySelector('#cancellationForm'),shift=nextShiftDate(job),hours=(shift-Date.now())/3600000;if(shift-Date.now()<CANCELLATION_CUTOFF_MS)return toast('Anulowanie online jest możliwe najpóźniej 8 godzin przed zmianą. W nagłej sytuacji skontaktuj się z pomocą Flexo.');form.jobId.value=jobId;form.cancelledBy.value=byWorker?'worker':'employer';form.querySelector('[data-cancel-title]').textContent=byWorker?'Nie możesz przyjść na zmianę?':'Anulować potwierdzoną zmianę?';form.querySelector('[data-cancel-job]').textContent=`${job.role} · ${job.company} · ${job.date}, ${job.time}`;form.querySelector('[data-cancel-warning]').innerHTML=hours<24?'<strong>Do zmiany zostało mniej niż 24 godziny.</strong> Nadal możesz anulować, ale decyzja zostanie oznaczona jako późna i zapisana w historii.':'Druga strona otrzyma informację, a decyzja zostanie zapisana w historii zlecenia.';form.reason.value='';form.details.value='';document.querySelector('#cancellationModal').showModal()}
function submitCancellation(form){const jobId=+form.jobId.value,job=jobs.find(j=>j.id===jobId),app=applications.find(a=>a.jobId===jobId&&a.status==='confirmed'),cancelledBy=form.cancelledBy.value;if(!job||!app)return toast('Ta zmiana została już zamknięta lub anulowana.');const byWorker=cancelledBy==='worker'&&authUser?.role==='user'&&app.workerEmail===authUser.email,byEmployer=cancelledBy==='employer'&&['employer','admin'].includes(authUser?.role)&&canManageJob(job);if(!byWorker&&!byEmployer)return;const shift=nextShiftDate(job);if(shift-Date.now()<CANCELLATION_CUTOFF_MS){document.querySelector('#cancellationModal').close();return toast('Minął termin anulowania online: wymagane jest minimum 8 godzin przed zmianą.')}const hoursBefore=Math.max(0,(shift-Date.now())/3600000),entry={id:`cancel-${jobId}-${Date.now()}`,jobId,applicationId:app.id,workerEmail:app.workerEmail,workerName:app.workerName,cancelledBy,reason:form.reason.value,details:form.details.value.trim(),cancelledAt:Date.now(),hoursBefore,late:hoursBefore<24};cancellations.push(entry);localStorage.setItem('flexo-cancellations',JSON.stringify(cancellations));if(byWorker){app.status='worker_cancelled';booked=booked.filter(id=>id!==jobId);localStorage.setItem('flexo-booked',JSON.stringify(booked));saveApplications()}else{app.status='employer_cancelled';job.active=false;job.cancelledByEmployer=true;job.cancellationReason=entry.reason;saveApplications();localStorage.setItem('flexo-jobs',JSON.stringify(jobs))}document.querySelector('#cancellationModal').close();renderJobs();renderBooked();renderAdminJobs();renderWorkerNotifications();if(jobsMap)updateMap();toast(byWorker?'Rezygnacja zapisana. Oferta znów jest dostępna dla innych.':'Zmiana anulowana. Pracownik otrzyma informację.')}
function setupCancellationWorkflow(){const modal=document.createElement('dialog');modal.id='cancellationModal';modal.className='cancellation-modal';modal.innerHTML=`<button class="modal-close" aria-label="Zamknij">×</button><form id="cancellationForm" class="cancellation-form"><input type="hidden" name="jobId"><input type="hidden" name="cancelledBy"><p class="eyebrow">ANULOWANIE POTWIERDZONEJ ZMIANY</p><h2 data-cancel-title></h2><p class="review-job" data-cancel-job></p><div class="cancellation-warning" data-cancel-warning></div><label>Powód rezygnacji<select name="reason" required><option value="">Wybierz powód</option><option value="health">Choroba lub nagła sytuacja zdrowotna</option><option value="family">Pilna sytuacja rodzinna</option><option value="schedule">Zmiana planów lub kolizja terminów</option><option value="operational">Zmiana potrzeb operacyjnych firmy</option><option value="other">Inny powód</option></select></label><label>Dodatkowa informacja (opcjonalnie)<textarea name="details" rows="3" maxlength="300" placeholder="Krótko wyjaśnij sytuację drugiej stronie"></textarea></label><p class="review-note">Anulowanie jest możliwe do rozpoczęcia zmiany. Powtarzające się lub późne rezygnacje mogą wpływać na wiarygodność konta.</p><button class="cancel-shift-confirm" type="submit">Potwierdzam anulowanie zmiany</button></form>`;document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close();modal.querySelector('form').onsubmit=e=>{e.preventDefault();submitCancellation(e.target)}}
function renderWorkerNotifications(){expireApplications();const box=document.querySelector('#workerNotifications');if(!box)return;if(authUser?.role!=='user'){box.hidden=true;return}const mine=applications.filter(a=>a.workerEmail===authUser.email).sort((a,b)=>b.appliedAt-a.appliedAt);box.hidden=!mine.length;box.innerHTML=mine.map(a=>{const j=jobs.find(x=>x.id===a.jobId);if(!j)return'';const texts={pending:['Oczekuje na potwierdzenie',`Pracodawca wybiera kandydata · pozostało <b data-deadline="${a.deadline}">${remainingTime(a.deadline)}</b>`],confirmed:['Zlecenie potwierdzone ✓','Pracodawca wybrał Ciebie. Zmiana jest w Twoim kalendarzu.'],completed:['Zmiana wykonana i oceniona ✓','Ocena pracodawcy została doliczona do średniej w Twoim profilu.'],rejected:['Wybrano inną osobę','Tym razem pracodawca wybrał innego kandydata. Może następnym razem!'],expired:['Brak decyzji w wymaganym czasie','Zgłoszenie wygasło — możesz wybrać inną zmianę.']}[a.status];return`<article class="application-notice ${a.status}"><span>${['confirmed','completed'].includes(a.status)?'✓':a.status==='pending'?'◷':'i'}</span><div><small>${j.role} · ${j.company}</small><strong>${texts[0]}</strong><p>${texts[1]}</p></div>${['confirmed','completed'].includes(a.status)?`<button onclick="openJob(${j.id})">Szczegóły</button>`:''}</article>`}).join('')}
